<section class="dashboard-shell"><div class="container"><div class="dashboard-head"><div><span class="eyebrow"><span></span> صندوق التواصل</span><h1>الرسائل</h1><p>الرسائل الواردة من نموذج التواصل العام.</p></div></div><div class="message-grid"><?php if (!$messages): ?><div class="panel empty-state"><span>✓</span><h3>لا توجد رسائل</h3><p>صندوق الرسائل فارغ حاليًا.</p></div><?php endif; ?><?php foreach ($messages as $message): ?><article class="message-card <?= $message['status'] === 'new' ? 'message-new' : '' ?>"><div><span class="status <?= $message['status'] === 'new' ? 'status-pending' : 'status-confirmed' ?>"><?= $message['status'] === 'new' ? 'جديدة' : 'مغلقة' ?></span><time><?= e(date('Y/m/d h:i A', strtotime($message['created_at']))) ?></time></div><h2><?= e($message['name']) ?></h2><p><?= nl2br(e($message['message'])) ?></p><footer><span><?= e($message['email']) ?><?= $message['phone'] ? ' · ' . e($message['phone']) : '' ?></span><?php if ($message['status'] !== 'closed'): ?><form method="post" action="<?= url('/messages/' . $message['id'] . '/close') ?>"><?= csrf_field() ?><button class="button button-ghost button-small">إغلاق</button></form><?php endif; ?></footer></article><?php endforeach; ?></div></div></section>
